def remove_k_balanced_substrings(s: str, k: int) -> str:
    # stack of runs [char, count]; a k-balanced block is k '(' followed by k ')'
    stack = []
    for ch in s:
        if stack and stack[-1][0] == ch:
            stack[-1][1] += 1
        else:
            stack.append([ch, 1])
        # a run of exactly k ')' directly after a run of at least k '(' forms a k-balanced block
        if ch == ')' and stack[-1][1] == k and len(stack) >= 2 and stack[-2][1] >= k:
            stack.pop()              # remove the k ')'
            stack[-1][1] -= k        # remove k '(' from the run below
            if stack[-1][1] == 0:
                stack.pop()
    return ''.join(c * cnt for c, cnt in stack)
